const ROLE_CONTAMINATION_PATTERNS = [
  { label: "teacherly_opener", pattern: /^(great|excellent)\b/i },
  { label: "teacherly_transition", pattern: /^let'?s\b/i },
  { label: "teacher_label", pattern: /^(\*\*)?teacher[:*]/i },
